#!/bin/bash
# s34_all_metrics.sh -- one table of the four metrics (MPKI, NormAT, NormPTW, NormIPC; base = 1 normalization + ref raw values, convention
# docs/feedback 09-13) for every finished b32 x S4096 pair: decode-own (ref -> ptwhop0; ref is the baseline), prefill-injected
# (base_prefill -> ptwhop0_prefill, ref = decode-own raw alongside), and remote prefill results (ref -> ptwhop0_mcm) in ~/kits/inbound.
# Writes analysis/s34_prefill_placement/ALL_FOUR_METRICS.md (+ .tsv). Uses h1_slice_four_metrics.py on symlinked views.
set -u
H=/home/user/accel-sim-docker/llm_exp; S=$H/scripts/h1_slice_four_metrics.py; OUT=$H/analysis/s34_prefill_placement/ALL_FOUR_METRICS
TSV=$OUT.tsv; MD=$OUT.md; printf 'set\tmodel\tphase\tpair\tkernels\ttokens\tref_cycles\tref_IPC\tref_MPKI\tref_L2hit\tref_AT\tref_PTW\tref_walk_remote\tbase_cycles\thop0_cycles\tNormIPC\tNormAT\tNormPTW\twalk_remote_base\n' > $TSV
row(){ # name model phase view kernels tokens
  local name=$1 model=$2 phase=$3 V=$4 K=$5 T=$6; local o; o=$(python3 $S $V 64k 1-$K $T 2>&1) || { echo "$name: $o" | head -2; return; }
  python3 - "$name" "$model" "$phase" "$K" "$T" "$o" >> $TSV <<'PY'
import re, sys
name, model, phase, K, T, o = sys.argv[1:7]
r1 = re.search(r"\[ref\]\s+warp insn ([\d,]+)\s+thread insn ([\d,]+)\s+cycles ([\d,]+)\s+IPC ([\d.]+)\s+L1 TLB hit ([\d.]+) %\s+L2 TLB hit ([\d.]+) %\s+unique L2 miss ([\d,]+)\s+MPKI ([\d.]+)", o)
r2 = re.search(r"remote PTW ratio ([\d.]+).*?PTW latency (\d+) = .*?AT (\d+)", o)
n = re.search(r"IPC base ([\d.]+) -> hop0 ([\d.]+) = ([\d.]+) \| AT ([\d.]+) -> ([\d.]+) = ([\d.]+) \| PTW ([\d.]+) -> ([\d.]+) = ([\d.]+) \| walk remote % base ([\d.]+) hop0 ([\d.]+).*?cycles base ([\d,]+) hop0 ([\d,]+)", o)
if not (r1 and r2 and n): sys.exit(0)
f = lambda s: s.replace(",", "")
print("\t".join([name, model, phase, "see md", K, T, f(r1.group(3)), r1.group(4), r1.group(8), r1.group(6), r2.group(3), r2.group(2), r2.group(1), f(n.group(12)), f(n.group(13)), n.group(3), n.group(6), n.group(9), n.group(10)]))
PY
}
mkview(){ local V=$1 ref=$2 base=$3 hop=$4; mkdir -p $V; ln -sfn $ref $V/ref_mcm; ln -sfn $base $V/base_mcm; ln -sfn $hop $V/ptwhop0_mcm; }
for m in Qwen3-30B-A3B Qwen3-32B Mixtral-8x7B-v0.1 Llama-3.3-70B-Instruct; do for cfgname in s4096_b0032_decode_layer0_v2 s1024_b0004_prefill_l0_decode_layer0_v2; do CAP=$H/llm_hypothesis1/$m/$cfgname; [ -d $CAP ] || continue
  K=$(grep -vc MemcpyHtoD $CAP/traces/kernelslist_decode.g); T=$(python3 -c "import json;print(json.load(open('$CAP/capture_info.json'))['batch'])")
  N=$CAP/sim_noprefill; [ -d $N ] || N=$CAP/sim
  SETTAG=$(echo $cfgname | grep -q s1024 && echo "S1024xb4 " || true)
  if grep -q '^EXIT=0' $N/ref_mcm/exit_code.txt 2>/dev/null && grep -q '^EXIT=0' $N/ptwhop0_mcm/exit_code.txt 2>/dev/null && [ -f $N/ref_mcm/NO_PREFILL_PLACEMENT.txt -o -d $CAP/sim_noprefill ]; then mkview $CAP/_view_decodeown $N/ref_mcm $N/ref_mcm $N/ptwhop0_mcm; row "${SETTAG}decode-own" $m decode $CAP/_view_decodeown $K $T; fi
  P=$CAP/sim_prefillchunked; if grep -q '^EXIT=0' $P/base_prefill/exit_code.txt 2>/dev/null && grep -q '^EXIT=0' $P/ptwhop0_prefill/exit_code.txt 2>/dev/null; then mkview $CAP/_view_injected $N/ref_mcm $P/base_prefill $P/ptwhop0_prefill; row "${SETTAG}prefill-injected" $m decode $CAP/_view_injected $K $T; fi
  [ "$cfgname" = s4096_b0032_decode_layer0_v2 ] || continue
  PRE=$H/llm_hypothesis1/$m/s4096_b0001_prefill_l0_decode_layer0_v2; for E in $(find /home/user/kits/inbound -type d -path "*${m}_s4096_b0001*" -name '*_prefill' 2>/dev/null); do
    grep -q '^EXIT=0' $E/ref_mcm/exit_code.txt 2>/dev/null || continue; hop=$E/ptwhop0_mcm; grep -q '^EXIT=0' $hop/exit_code.txt 2>/dev/null || hop=$E/ptwhop0_ft; grep -q '^EXIT=0' $hop/exit_code.txt 2>/dev/null || continue
    KP=$(grep -vc MemcpyHtoD $PRE/traces/kernelslist_prefill.g); mkview $E/_view $E/ref_mcm $E/ref_mcm $hop; row "prefill-remote($(basename $hop))" $m prefill $E/_view $KP 4096; done
done; done
python3 - $TSV $MD <<'PY'
import sys, csv
rows = list(csv.DictReader(open(sys.argv[1]), delimiter="\t"))
L = ["# b32 x S4096 four metrics (all finished pairs) -- generated by scripts/s34_all_metrics.sh", "",
     "| set | model | phase | kernels | ref cycles | ref IPC | ref MPKI | ref L2 hit % | ref AT | ref PTW | ref walk remote | base cycles | hop0 cycles | **NormIPC** | **NormAT** | **NormPTW** | walk remote % (base) |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
for r in rows:
    L.append(f"| {r['set']} | {r['model']} | {r['phase']} | {r['kernels']} | {int(r['ref_cycles']):,} | {r['ref_IPC']} | {r['ref_MPKI']} | {r['ref_L2hit']} | {r['ref_AT']} | {r['ref_PTW']} | {r['ref_walk_remote']} | {int(r['base_cycles']):,} | {int(r['hop0_cycles']):,} | **{r['NormIPC']}** | **{r['NormAT']}** | **{r['NormPTW']}** | {r['walk_remote_base']} |")
L += ["", "- decode-own: base = ref (decode-own first touch), hop0 = ptwhop0_mcm (ref map exact replay). prefill-injected: base = base_prefill (predicted prefill map), hop0 = ptwhop0_prefill (base's saved map exact replay); ref columns = decode-own ref raw values for comparison. prefill-remote: remote-server, base = ref.",
      "- MPKI = unique L2 TLB misses / warp kilo-insn (ref arm); PTW = l2_mshr_full + pwq_wait + walk_svc (out=PTW); AT = out=ALL avg; Norm* = hop0 / base."]
open(sys.argv[2], "w").write("\n".join(L) + "\n"); print("\n".join(L))
PY
